"about_items": [
{
"n": "#52·11",
"text": "A grey blazer in a classic straight cut with notched lapels, featuring four buttons down the front and flap pockets; its fabric has a soft sheen and falls just past the hip."
},
{
"n": "#118·22",
"text": "A white linen mini skirt with a clean A-line shape, secured by a central back zipper and finished with a small metallic logo on the right side seam; the fabric drapes lightly and sits above the knee."
},
{
"n": "#148·02",
"text": "White leather platform sandals adorned with a sculpted gold starfish embellishment on the strap, set on a thick white sole for comfort and height; the open toe design keeps the foot feeling light."
},
{
"n": "#393·02",
"text": "A beige handbag combining smooth leather and suede textures, accented by a silver triangular clasp and a detachable shoulder strap that allows versatile carrying options; its rounded silhouette holds essentials without bulk."
}
]
